  "album"."id",
  "album"."albumName" as "name",
  "album"."createdAt",
  "album"."isLocked",
  (
    exists (
      select
        1
      from
        album_user member
      where
        member."albumId" = album.id
        and member.role <> $1
    )
    or exists (
      select
        1
      from
        shared_link
      where
        shared_link."albumId" = album.id
    )
    or exists (
      select
        1
      from
        shared_space_album linked
      where
        linked."linkedAlbumId" = album.id
    )
  ) as "shared"
from
  "album"
  inner join "album_user" as "owner" on "owner"."albumId" = "album"."id"
  and "owner"."userId" = $2
  and "owner"."role" = $3
where
  "album"."deletedAt" is null
  and "album"."kind" = $4
  and "album"."parentId" is null
  and "album"."libraryScope" = $5
  and not exists (
    select
      1
    from
      public.album_origin origin
    where
      origin."albumId" = album.id
  )
order by
  "album"."createdAt",
  "album"."id"

