-- AlbumCleanupRepository.getAlbumStats
select
  "album_asset"."albumId",
  count(*)::int as "count",
  (
    count(*) filter (
      where
        asset_exif.latitude is not null
        and asset_exif.longitude is not null
    )
  )::int as "located",
  min(asset."localDateTime") filter (
    where
      not coalesce(
        asset_exif."estimatedDateTimeOriginal" = asset_exif."dateTimeOriginal",
        false
      )
  ) as "from",
  max(asset."localDateTime") filter (
    where
      not coalesce(
        asset_exif."estimatedDateTimeOriginal" = asset_exif."dateTimeOriginal",
        false
      )
  ) as "to",
  percentile_disc(0.5) within group (
    order by
      asset."localDateTime"
  ) filter (
    where
      not coalesce(
        asset_exif."estimatedDateTimeOriginal" = asset_exif."dateTimeOriginal",
        false
      )
  ) as "middle"
from
  "asset"
  inner join "album_asset" on "album_asset"."assetId" = "asset"."id"
  left join "asset_exif" on "asset_exif"."assetId" = "asset"."id"
where
  (
    "asset"."visibility" in ('archive', 'timeline')
    and not exists (
      select
        1
      from
        asset_lock
      where
        asset_lock."assetId" = "asset"."id"
    )
  )
  and "asset"."deletedAt" is null
  and "album_asset"."albumId" = any ($1::uuid[])
group by
  "album_asset"."albumId"

