-- AlbumCleanupRepository.getOverlaps
select
  "first"."albumId" as "firstId",
  "second"."albumId" as "secondId",
  count(*)::int as "shared"
from
  "asset"
  inner join "album_asset" as "first" on "first"."assetId" = "asset"."id"
  inner join "album_asset" as "second" on "second"."assetId" = "asset"."id"
  and "second"."albumId" > "first"."albumId"
where
  (
    "asset"."visibility" in ('archive', 'timeline')
    and not exists (
      select
        1
      from
        asset_lock
      where
        asset_lock."assetId" = "asset"."id"
    )
  )
  and "asset"."deletedAt" is null
  and "first"."albumId" = any ($1::uuid[])
